static uint32_t get_power_of_two(uint32_t n) {
    if (n <= 1) return 1;
    n--;
    uint32_t p = 1;
    while (p < n) {
        p <<= 1;
    }
    return p;
}

static uint32_t log2_floor(uint32_t n) {
    uint32_t log = 0;
    while (n > 1) {
        n >>= 1;
        log++;
    }
    return log;
}

static uint32_t count_bits(uint32_t n) {
    uint32_t count = 0;
    while (n > 0) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

